CREATE TABLE public.help_articles (id uuid DEFAULT gen_random_uuid() NOT NULL, slug text NOT NULL, title text NOT NULL, body text NOT NULL, category text, audience text DEFAULT 'all'::text NOT NULL, sort_order smallint DEFAULT 0 NOT NULL, is_published boolean DEFAULT true NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
ALTER TABLE public.help_articles ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.help_articles ADD CONSTRAINT help_articles_audience_check CHECK (audience = ANY (ARRAY['diabetic'::text, 'non_diabetic'::text, 'all'::text]));
ALTER TABLE public.help_articles ADD CONSTRAINT help_articles_pkey PRIMARY KEY (id);
ALTER TABLE public.help_articles ADD CONSTRAINT help_articles_slug_key UNIQUE (slug);
GRANT MAINTAIN, REFERENCES, TRIGGER, TRUNCATE ON public.help_articles TO anon;
GRANT MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE ON public.help_articles TO authenticated;
GRANT ALL ON public.help_articles TO service_role;
CREATE INDEX help_articles_category_sort_idx ON public.help_articles (category, sort_order);
CREATE TRIGGER help_articles_set_updated_at BEFORE UPDATE ON public.help_articles FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();
CREATE POLICY "Published help articles are viewable by all authenticated users" ON public.help_articles FOR SELECT TO authenticated USING (is_published);
CREATE TABLE public.help_videos (id uuid DEFAULT gen_random_uuid() NOT NULL, article_id uuid, title text NOT NULL, video_url text NOT NULL, thumbnail_url text, duration_seconds integer, sort_order smallint DEFAULT 0 NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL);
ALTER TABLE public.help_videos ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.help_videos ADD CONSTRAINT help_videos_article_id_fkey FOREIGN KEY (article_id) REFERENCES public.help_articles(id) ON DELETE SET NULL;
ALTER TABLE public.help_videos ADD CONSTRAINT help_videos_pkey PRIMARY KEY (id);
GRANT MAINTAIN, REFERENCES, TRIGGER, TRUNCATE ON public.help_videos TO anon;
GRANT MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE ON public.help_videos TO authenticated;
GRANT ALL ON public.help_videos TO service_role;
CREATE INDEX help_videos_article_id_idx ON public.help_videos (article_id);
CREATE INDEX help_videos_sort_idx ON public.help_videos (sort_order);
CREATE POLICY "Help videos are viewable by all authenticated users" ON public.help_videos FOR SELECT TO authenticated USING (true);
CREATE TABLE public.support_messages (id uuid DEFAULT gen_random_uuid() NOT NULL, support_request_id uuid NOT NULL, user_id uuid NOT NULL, role text NOT NULL, content text NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL);
ALTER TABLE public.support_messages ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.support_messages ADD CONSTRAINT support_messages_pkey PRIMARY KEY (id);
ALTER TABLE public.support_messages ADD CONSTRAINT support_messages_role_check CHECK (role = ANY (ARRAY['user'::text, 'assistant'::text]));
ALTER TABLE public.support_messages ADD CONSTRAINT support_messages_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;
GRANT MAINTAIN, REFERENCES, TRIGGER, TRUNCATE ON public.support_messages TO anon;
GRANT INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE ON public.support_messages TO authenticated;
GRANT ALL ON public.support_messages TO service_role;
CREATE INDEX support_messages_request_created_at_idx ON public.support_messages (support_request_id, created_at);
CREATE POLICY "Support messages are insertable by owner" ON public.support_messages FOR INSERT TO authenticated WITH CHECK ((( SELECT auth.uid() AS uid) = user_id));
CREATE POLICY "Support messages are viewable by owner" ON public.support_messages FOR SELECT TO authenticated USING ((( SELECT auth.uid() AS uid) = user_id));
CREATE TABLE public.support_requests (id uuid DEFAULT gen_random_uuid() NOT NULL, user_id uuid NOT NULL, subject text NOT NULL, message text NOT NULL, email text NOT NULL, status text DEFAULT 'open'::text NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
ALTER TABLE public.support_requests ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.support_requests ADD CONSTRAINT support_requests_pkey PRIMARY KEY (id);
ALTER TABLE public.support_messages ADD CONSTRAINT support_messages_support_request_id_fkey FOREIGN KEY (support_request_id) REFERENCES public.support_requests(id) ON DELETE CASCADE;
ALTER TABLE public.support_requests ADD CONSTRAINT support_requests_status_check CHECK (status = ANY (ARRAY['open'::text, 'closed'::text]));
ALTER TABLE public.support_requests ADD CONSTRAINT support_requests_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;
GRANT MAINTAIN, REFERENCES, TRIGGER, TRUNCATE ON public.support_requests TO anon;
GRANT INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE ON public.support_requests TO authenticated;
GRANT ALL ON public.support_requests TO service_role;
CREATE INDEX support_requests_user_created_at_idx ON public.support_requests (user_id, created_at DESC);
CREATE TRIGGER support_requests_set_updated_at BEFORE UPDATE ON public.support_requests FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();
CREATE POLICY "Support requests are insertable by owner" ON public.support_requests FOR INSERT TO authenticated WITH CHECK ((( SELECT auth.uid() AS uid) = user_id));
CREATE POLICY "Support requests are viewable by owner" ON public.support_requests FOR SELECT TO authenticated USING ((( SELECT auth.uid() AS uid) = user_id));
